begin;
set local search_path=public,extensions;
select plan(23);
select ok((select p.prosecdef and p.proconfig::text like'%search_path=%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='private'and p.proname='franchise_crm_row_access'),'CRM row access is hardened security definer');
select ok((select pg_get_functiondef(p.oid)like'%FRANCHISE_OWNER%'and pg_get_functiondef(p.oid)like'%FRANCHISE_MANAGER%'and pg_get_functiondef(p.oid)like'%FRANCHISE_VIEWER%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='private'and p.proname='franchise_crm_row_access'),'operator CRM roles are explicit');
select ok((select pg_get_functiondef(p.oid)not like'%FINANCE_MANAGER%'and pg_get_functiondef(p.oid)not like'%LIBRARY_MANAGER%'and pg_get_functiondef(p.oid)not like'%READ_ONLY_AUDITOR%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='private'and p.proname='franchise_crm_row_access'),'global finance, library and auditor roles cannot read CRM PII');
select ok((select pg_get_functiondef(p.oid)like'%t.franchise_id=f.id%'and pg_get_functiondef(p.oid)like'%t.id=p_territory_version_id%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='private'and p.proname='franchise_crm_row_access'),'access requires the exact territory version of the franchise');
select ok((select count(*)=3 from pg_policies where schemaname='public'and policyname=any(array['franchise_prospects_operator_territory_read','franchise_activities_operator_territory_read','franchise_pipeline_operator_territory_read'])),'three hardened CRM read policies exist');
select ok(not exists(select 1 from pg_policies where schemaname='public'and policyname=any(array['franchise_prospects_scoped_read','franchise_activities_scoped_read','franchise_pipeline_scoped_read'])),'broad legacy franchise_access policies are removed');
select ok((select qual like'%franchise_crm_row_access(franchise_id, territory_version_id%'from pg_policies where schemaname='public'and tablename='franchise_crm_prospects'and policyname='franchise_prospects_operator_territory_read'),'prospect policy is franchise and territory scoped');
select ok((select qual like'%p.id = franchise_crm_activities.prospect_id%'and qual like'%p.franchise_id = franchise_crm_activities.franchise_id%'and qual like'%franchise_crm_row_access%'from pg_policies where schemaname='public'and tablename='franchise_crm_activities'and policyname='franchise_activities_operator_territory_read'),'activity policy binds its prospect and qualified outer franchise');
select ok((select qual like'%p.id = franchise_pipeline_events.prospect_id%'and qual like'%p.franchise_id = franchise_pipeline_events.franchise_id%'and qual like'%franchise_crm_row_access%'from pg_policies where schemaname='public'and tablename='franchise_pipeline_events'and policyname='franchise_pipeline_operator_territory_read'),'pipeline policy binds its prospect and qualified outer franchise');
select ok((select count(*)=1 from pg_trigger t join pg_class c on c.oid=t.tgrelid where c.oid='public.franchise_crm_prospects'::regclass and t.tgname='franchise_crm_owner_membership_guard'and not t.tgisinternal),'owner membership guard is installed');
select ok((select pg_get_functiondef(p.oid)like'%m.organization_id=operator_org%'and pg_get_functiondef(p.oid)like'%m.user_id=new.owner_user_id%'and pg_get_functiondef(p.oid)like'%m.status=''ACTIVE''%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='private'and p.proname='guard_franchise_crm_owner_membership'),'owner must be an active member of the operator organization');
select ok((select pg_get_functiondef(p.oid)like'%FRANCHISE_CRM_OWNER_NOT_ACTIVE_MEMBER%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='private'and p.proname='guard_franchise_crm_owner_membership'),'invalid owner assignment fails closed');
select ok((select p.prosecdef and p.proconfig::text like'%search_path=%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='list_franchise_crm_aggregate_metrics'),'auditor aggregate RPC is hardened');
select ok((select pg_get_functiondef(p.oid)like'%READ_ONLY_AUDITOR%'and pg_get_functiondef(p.oid)like'%count(*)%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='list_franchise_crm_aggregate_metrics'),'auditor access exposes aggregate counts');
select ok((select pg_get_functiondef(p.oid)not like'%contact_email%'and pg_get_functiondef(p.oid)not like'%display_name%'and pg_get_functiondef(p.oid)not like'%organization_name%'and pg_get_functiondef(p.oid)not like'%summary%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='list_franchise_crm_aggregate_metrics'),'aggregate RPC contains no CRM PII fields');
select ok(has_function_privilege('authenticated','public.list_franchise_crm_aggregate_metrics(uuid,uuid)','EXECUTE')and not has_function_privilege('anon','public.list_franchise_crm_aggregate_metrics(uuid,uuid)','EXECUTE')and not has_function_privilege('service_role','public.list_franchise_crm_aggregate_metrics(uuid,uuid)','EXECUTE'),'aggregate RPC grants are least privilege');
select ok(not has_table_privilege('authenticated','public.franchise_crm_prospects','INSERT')and not has_table_privilege('authenticated','public.franchise_crm_prospects','UPDATE'),'direct PII writes remain denied');
select ok((select count(*)=3 and bool_and(c.relrowsecurity)from pg_class c where c.oid=any(array['public.franchise_crm_prospects'::regclass,'public.franchise_crm_activities'::regclass,'public.franchise_pipeline_events'::regclass])),'RLS remains enabled on all CRM records');
select ok(private.valid_franchise_performance_measurements('[{"metric_version_id":"11111111-1111-4111-8111-111111111111","numerator":"8","denominator":"10","evidence_refs":["audit:1"]}]'::jsonb),'ALLOW: one strict bounded KPI measurement is accepted');
select ok(not private.valid_franchise_performance_measurements((select jsonb_agg(jsonb_build_object('metric_version_id',lpad(to_hex(i),8,'0')||'-1111-4111-8111-111111111111','numerator','1','denominator','1','evidence_refs','[]'::jsonb))from generate_series(1,101)i)),'DENY: more than 100 measurements are rejected');
select ok(not private.valid_franchise_performance_measurements('[{"metric_version_id":"11111111-1111-4111-8111-111111111111","numerator":"8","denominator":"10","evidence_refs":[],"weight_basis_points":10000}]'::jsonb),'DENY: an unexpected client-controlled weight is rejected');
select ok(not private.valid_franchise_performance_measurements('[{"metric_version_id":"11111111-1111-4111-8111-111111111111","numerator":"8","denominator":"10","evidence_refs":[]},{"metric_version_id":"11111111-1111-4111-8111-111111111111","numerator":"9","denominator":"10","evidence_refs":[]}]'::jsonb),'DENY: duplicate metric versions are rejected');
select ok(not private.valid_franchise_performance_measurements('[{"metric_version_id":"11111111-1111-4111-8111-111111111111","numerator":"NaN","denominator":"0","evidence_refs":{}}]'::jsonb),'DENY: non-integer values, zero denominator and non-array evidence are rejected');
select * from finish();rollback;
